"use client";

import {
  type CinResult,
  formatUdyam,
  type HsnResult,
  validateCin,
  validateFssai,
  validateHsn,
  validateTan,
  validateUdyam,
} from "../../lib/business-ids";
import type { IdResult } from "../../lib/gov-ids";
import { IdentifierInput, type IdentifierInputProps } from "./identifier-input";

type WrapperProps<T extends { valid: boolean; error?: { message: string } }> =
  Omit<IdentifierInputProps<T>, "validate" | "transform" | "badge">;

const alnum = (max: number) => (raw: string) =>
  raw
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, "")
    .slice(0, max);

const digits = (max: number) => (raw: string) =>
  raw.replace(/\D/g, "").slice(0, max);

/** TAN — the deductor's tax account number, `MUMA12345B`. */
export function TANInput(props: WrapperProps<IdResult>) {
  return (
    <IdentifierInput<IdResult>
      placeholder="MUMA12345B"
      {...props}
      validate={validateTan}
      transform={alnum(10)}
    />
  );
}

/**
 * CIN — 21 characters that decode to listing status, state, incorporation year
 * and company class. The badge shows the class, which is the part people check.
 */
export function CINInput(props: WrapperProps<CinResult>) {
  return (
    <IdentifierInput<CinResult>
      placeholder="U72200KA2013PTC098765"
      tracking="tracking-[0.04em]"
      {...props}
      validate={validateCin}
      transform={alnum(21)}
      badge={(result) => result.ownership}
    />
  );
}

/** Udyam (MSME) registration — `UDYAM-KR-03-0000001`. */
export function UdyamInput(props: WrapperProps<IdResult>) {
  return (
    <IdentifierInput<IdResult>
      placeholder="UDYAM-KR-03-0000001"
      tracking="tracking-[0.04em]"
      {...props}
      validate={validateUdyam}
      // Hyphens are re-inserted as you type, matching how it's printed.
      transform={formatUdyam}
    />
  );
}

/** HSN / SAC code — 2, 4, 6 or 8 digits. The badge names the level. */
export function HSNInput(props: WrapperProps<HsnResult>) {
  return (
    <IdentifierInput<HsnResult>
      placeholder="998314"
      tracking="tracking-[0.18em]"
      {...props}
      validate={validateHsn}
      transform={digits(8)}
      badge={(result) => result.level}
    />
  );
}

/** FSSAI food licence number — 14 digits. */
export function FSSAIInput(props: WrapperProps<IdResult>) {
  return (
    <IdentifierInput<IdResult>
      placeholder="12345678901234"
      tracking="tracking-[0.12em]"
      {...props}
      validate={validateFssai}
      transform={digits(14)}
    />
  );
}

export type TANInputProps = WrapperProps<IdResult>;
export type CINInputProps = WrapperProps<CinResult>;
export type UdyamInputProps = WrapperProps<IdResult>;
export type HSNInputProps = WrapperProps<HsnResult>;
export type FSSAIInputProps = WrapperProps<IdResult>;

"use client";

import { type ClassValue, clsx } from "clsx";
import { CircleAlert, Info } from "lucide-react";
import * as React from "react";
import { twMerge } from "tailwind-merge";

/**
 * Shared by every bharat-ui field. Defined here rather than imported from a
 * project's `@/lib/utils` so that installing a component can never overwrite
 * the consumer's own utils file.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export type FieldTone = "error" | "hint" | "muted";

export interface FieldProps {
  id: string;
  /** Id of the element holding the message; wire this into aria-describedby. */
  messageId: string;
  label?: string;
  /** Resolved message text — an error, a warning, or the fallback description. */
  message?: string;
  tone?: FieldTone;
  className?: string;
  children: React.ReactNode;
}

/** Label + control + message, with the aria plumbing already correct. */
export function Field({
  id,
  messageId,
  label,
  message,
  tone = "muted",
  className,
  children,
}: FieldProps) {
  return (
    <div className={cn("w-full", className)}>
      {label && (
        <label htmlFor={id} className="mb-1.5 block text-sm font-medium">
          {label}
        </label>
      )}

      {children}

      {message && (
        <p
          id={messageId}
          // Only errors interrupt a screen reader; hints are read on focus.
          role={tone === "error" ? "alert" : undefined}
          className={cn(
            "mt-1.5 flex items-start gap-1.5 text-xs",
            tone === "error"
              ? "text-red-600 dark:text-red-400"
              : "text-neutral-500 dark:text-neutral-400",
          )}
        >
          {tone === "error" ? (
            <CircleAlert className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : tone === "hint" ? (
            <Info className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : null}
          {message}
        </p>
      )}
    </div>
  );
}

/** Border/ring classes shared by every text control, keyed on validity. */
export function controlClasses(state: {
  error?: boolean;
  success?: boolean;
}): string {
  return cn(
    "h-10 w-full rounded-lg border bg-transparent px-3 py-2 font-mono text-sm outline-none transition",
    "placeholder:font-sans placeholder:text-neutral-400 dark:placeholder:text-neutral-600",
    "disabled:cursor-not-allowed disabled:opacity-50",
    "focus-visible:ring-[3px]",
    state.error
      ? "border-red-500 focus-visible:ring-red-500/20"
      : state.success
        ? "border-emerald-500 focus-visible:ring-emerald-500/20"
        : "border-neutral-300 focus-visible:border-neutral-900 focus-visible:ring-neutral-900/10 dark:border-neutral-700 dark:focus-visible:border-neutral-300 dark:focus-visible:ring-neutral-100/10",
  );
}

export interface ValidationLike {
  valid: boolean;
  error?: { message: string };
}

/**
 * The controlled/uncontrolled + touched + report-upward logic every field here
 * needs. Kept in one place so all of them behave identically: errors appear on
 * blur by default, then update live once the user has been warned.
 */
export function useFieldState<T extends ValidationLike>(options: {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: T) => void;
  validate: (raw: string) => T;
  /** Optional input mask applied on every keystroke. */
  transform?: (raw: string) => string;
  validateOn?: "blur" | "change";
}) {
  const {
    value: controlled,
    defaultValue = "",
    onValueChange,
    onValidationChange,
    validate,
    transform,
    validateOn = "blur",
  } = options;

  const isControlled = controlled !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue);
  const value = isControlled ? controlled : uncontrolled;
  const [touched, setTouched] = React.useState(false);

  const result = React.useMemo(() => validate(value), [value, validate]);

  // Report upward only when the outcome actually changes, so consumers can put
  // setState directly in the callback without a render loop.
  const lastReported = React.useRef<string>("");
  React.useEffect(() => {
    const key = JSON.stringify(result);
    if (key === lastReported.current) return;
    lastReported.current = key;
    onValidationChange?.(result);
  }, [result, onValidationChange]);

  const setValue = React.useCallback(
    (next: string) => {
      const masked = transform ? transform(next) : next;
      if (!isControlled) setUncontrolled(masked);
      onValueChange?.(masked);
    },
    [isControlled, onValueChange, transform],
  );

  const shouldValidate = validateOn === "change" || touched;
  const error =
    shouldValidate && value.trim() !== "" ? result.error?.message : undefined;

  return {
    value,
    setValue,
    result,
    touched,
    markTouched: () => setTouched(true),
    error,
    success: result.valid,
  };
}

/** Small right-aligned badge inside a control (bank name, entity type, …). */
export function FieldBadge({ children }: { children: React.ReactNode }) {
  return (
    <span className="pointer-events-none absolute right-2 top-1/2 flex max-w-[45%] -translate-y-1/2 items-center gap-1 truncate rounded-full bg-emerald-500/10 px-2 py-0.5 text-xs font-medium text-emerald-700 dark:text-emerald-400">
      {children}
    </span>
  );
}

"use client";

import * as React from "react";

import {
  cn,
  controlClasses,
  Field,
  FieldBadge,
  useFieldState,
  type ValidationLike,
} from "./field";

export interface IdentifierInputProps<T extends ValidationLike>
  extends Omit<
    React.ComponentProps<"input">,
    "value" | "defaultValue" | "onChange" | "type"
  > {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: T) => void;
  validateOn?: "blur" | "change";
  validate: (raw: string) => T;
  /** Input mask applied on every keystroke. */
  transform?: (raw: string) => string;
  /** Derives the right-hand badge from a valid result. */
  badge?: (result: T) => string | undefined;
  label?: string;
  description?: string;
  containerClassName?: string;
  /** Extra letter-spacing suits fixed-format identifiers. */
  tracking?: string;
}

/**
 * The shared body of every fixed-format identifier field. The specific
 * components (PAN, TAN, CIN, …) are thin wrappers that supply a validator, a
 * mask and a placeholder — everything else behaves identically by construction.
 */
export function IdentifierInput<T extends ValidationLike>({
  value: controlledValue,
  defaultValue = "",
  onValueChange,
  onValidationChange,
  validateOn = "blur",
  validate,
  transform,
  badge,
  label,
  description,
  className,
  containerClassName,
  tracking = "tracking-[0.12em]",
  id,
  onBlur,
  ...props
}: IdentifierInputProps<T>) {
  const reactId = React.useId();
  const inputId = id ?? `id-${reactId}`;
  const messageId = `${inputId}-message`;

  const field = useFieldState<T>({
    value: controlledValue,
    defaultValue,
    onValueChange,
    onValidationChange,
    validate,
    transform,
    validateOn,
  });

  const badgeText =
    badge && field.result.valid ? badge(field.result) : undefined;

  return (
    <Field
      id={inputId}
      messageId={messageId}
      label={label}
      message={field.error ?? description}
      tone={field.error ? "error" : "muted"}
      className={containerClassName}
    >
      <div className="relative">
        <input
          {...props}
          id={inputId}
          type="text"
          autoComplete="off"
          autoCapitalize="characters"
          autoCorrect="off"
          spellCheck={false}
          value={field.value}
          onChange={(event) => field.setValue(event.target.value)}
          onBlur={(event) => {
            field.markTouched();
            onBlur?.(event);
          }}
          aria-invalid={Boolean(field.error)}
          aria-describedby={messageId}
          className={cn(
            controlClasses({
              error: Boolean(field.error),
              success: field.success,
            }),
            tracking,
            badgeText && "pr-36",
            className,
          )}
        />
        {badgeText && <FieldBadge>{badgeText}</FieldBadge>}
      </div>
    </Field>
  );
}

/**
 * Business and tax identifiers: TAN, CIN, Udyam, HSN/SAC and FSSAI licence.
 *
 * CIN is the interesting one — 21 characters that encode the listing status,
 * industry, state, incorporation year, ownership type and registration number,
 * all of which can be decoded offline.
 */

import type { IdResult } from "./gov-ids";

function bad<E extends string>(
  code: E,
  message: string,
  normalized: string,
): IdResult<E> {
  return { valid: false, normalized, error: { code, message } };
}

const upper = (input: string) => input.replace(/[\s-]/g, "").toUpperCase();

/* ── TAN ─────────────────────────────────────────────────────────────────── */

const TAN_RE = /^[A-Z]{4}[0-9]{5}[A-Z]$/;

export type TanErrorCode = "empty" | "wrong_length" | "bad_shape";

/**
 * Tax Deduction Account Number: `AAAA99999A`. The first three letters are the
 * city code of the issuing office, the fourth is the deductor's initial.
 */
export function validateTan(input: string): IdResult<TanErrorCode> {
  const tan = upper(input);
  if (!input.trim()) return bad("empty", "Enter a TAN.", tan);
  if (tan.length !== 10) {
    return bad(
      "wrong_length",
      `A TAN is 10 characters — ${tan.length} so far.`,
      tan,
    );
  }
  if (!TAN_RE.test(tan)) {
    return bad(
      "bad_shape",
      "A TAN looks like MUMA12345B — four letters, five digits, one letter.",
      tan,
    );
  }
  return { valid: true, normalized: tan };
}

/* ── CIN ─────────────────────────────────────────────────────────────────── */

const CIN_RE = /^([LU])(\d{5})([A-Z]{2})(\d{4})([A-Z]{3})(\d{6})$/;

const OWNERSHIP: Readonly<Record<string, string>> = {
  PLC: "Public Limited Company",
  PTC: "Private Limited Company",
  OPC: "One Person Company",
  FLC: "Financial Lease Company",
  GAP: "General Association Public",
  GAT: "General Association Private",
  FTC: "Subsidiary of a Foreign Company",
  ULL: "Unlimited Liability, Public",
  ULT: "Unlimited Liability, Private",
  NPL: "Not-for-Profit (Section 8)",
  SGC: "State Government Company",
  GOI: "Government of India Company",
};

export type CinErrorCode =
  | "empty"
  | "wrong_length"
  | "bad_shape"
  | "unknown_state"
  | "bad_year"
  | "unknown_ownership";

export interface CinResult extends IdResult<CinErrorCode> {
  listed?: boolean;
  industryCode?: string;
  stateCode?: string;
  state?: string;
  year?: number;
  ownershipCode?: string;
  ownership?: string;
  registrationNumber?: string;
}

/** Corporate Identity Number — 21 characters, fully decodable offline. */
export function validateCin(input: string): CinResult {
  const cin = upper(input);
  if (!input.trim()) return bad("empty", "Enter a CIN.", cin);
  if (cin.length !== 21) {
    return bad(
      "wrong_length",
      `A CIN is 21 characters — ${cin.length} so far.`,
      cin,
    );
  }

  const match = CIN_RE.exec(cin);
  if (!match) {
    return bad("bad_shape", "A CIN looks like U72200KA2013PTC098765.", cin);
  }

  const [
    ,
    listing,
    industryCode,
    stateCode,
    yearStr,
    ownershipCode,
    registrationNumber,
  ] = match;

  const state = CIN_STATE_CODES[stateCode];
  if (!state)
    return bad(
      "unknown_state",
      `“${stateCode}” isn't a state code we recognise.`,
      cin,
    );

  const year = Number(yearStr);
  const thisYear = new Date().getFullYear();
  if (year < 1850 || year > thisYear) {
    return bad(
      "bad_year",
      `“${yearStr}” isn't a plausible incorporation year.`,
      cin,
    );
  }

  const ownership = OWNERSHIP[ownershipCode];
  if (!ownership) {
    return bad(
      "unknown_ownership",
      `“${ownershipCode}” isn't a company class we recognise.`,
      cin,
    );
  }

  return {
    valid: true,
    normalized: cin,
    // 'L' means listed on a stock exchange, 'U' unlisted.
    listed: listing === "L",
    industryCode,
    stateCode,
    state,
    year,
    ownershipCode,
    ownership,
    registrationNumber,
  };
}

/** CIN uses two-letter state abbreviations, not GST's numeric state codes. */
const CIN_STATE_CODES: Readonly<Record<string, string>> = {
  AP: "Andhra Pradesh",
  AR: "Arunachal Pradesh",
  AS: "Assam",
  BR: "Bihar",
  CG: "Chhattisgarh",
  CH: "Chandigarh",
  DL: "Delhi",
  GA: "Goa",
  GJ: "Gujarat",
  HR: "Haryana",
  HP: "Himachal Pradesh",
  JH: "Jharkhand",
  JK: "Jammu & Kashmir",
  KA: "Karnataka",
  KL: "Kerala",
  LA: "Ladakh",
  MH: "Maharashtra",
  ML: "Meghalaya",
  MN: "Manipur",
  MP: "Madhya Pradesh",
  MZ: "Mizoram",
  NL: "Nagaland",
  OD: "Odisha",
  OR: "Odisha (old code)",
  PB: "Punjab",
  PY: "Puducherry",
  RJ: "Rajasthan",
  SK: "Sikkim",
  TN: "Tamil Nadu",
  TR: "Tripura",
  TS: "Telangana",
  UK: "Uttarakhand",
  UR: "Uttarakhand (old code)",
  UP: "Uttar Pradesh",
  WB: "West Bengal",
  AN: "Andaman & Nicobar Islands",
  DN: "Dadra & Nagar Haveli",
  DD: "Daman & Diu",
  LD: "Lakshadweep",
};

/* ── Udyam (MSME) ────────────────────────────────────────────────────────── */

const UDYAM_RE = /^UDYAM[A-Z]{2}\d{2}\d{7}$/;

export type UdyamErrorCode = "empty" | "bad_shape";

/** Udyam registration: `UDYAM-KR-03-0000001`. Replaced Udyog Aadhaar in 2020. */
export function validateUdyam(input: string): IdResult<UdyamErrorCode> {
  const id = upper(input);
  if (!input.trim())
    return bad("empty", "Enter a Udyam registration number.", id);
  if (!UDYAM_RE.test(id)) {
    return bad("bad_shape", "Udyam numbers look like UDYAM-KR-03-0000001.", id);
  }
  return { valid: true, normalized: id };
}

/** Re-insert the hyphens Udyam numbers are printed with. */
export function formatUdyam(input: string): string {
  const id = upper(input).slice(0, 16);
  if (id.length <= 5) return id;
  const parts = [id.slice(0, 5), id.slice(5, 7), id.slice(7, 9), id.slice(9)];
  return parts.filter(Boolean).join("-");
}

/* ── HSN / SAC ───────────────────────────────────────────────────────────── */

export type HsnErrorCode = "empty" | "not_digits" | "bad_length";

export interface HsnResult extends IdResult<HsnErrorCode> {
  /** 2 = chapter, 4 = heading, 6 = subheading, 8 = tariff item. */
  level?: "chapter" | "heading" | "subheading" | "tariff item";
}

/** HSN (goods) and SAC (services) codes are 2, 4, 6 or 8 digits — never 3, 5 or 7. */
export function validateHsn(input: string): HsnResult {
  const code = input.replace(/\D/g, "");
  if (!input.trim()) return bad("empty", "Enter an HSN or SAC code.", code);
  if (/[^\d\s]/.test(input))
    return bad("not_digits", "HSN codes are digits only.", code);

  const levels = {
    2: "chapter",
    4: "heading",
    6: "subheading",
    8: "tariff item",
  } as const;
  const level = levels[code.length as keyof typeof levels];
  if (!level) {
    return bad("bad_length", "An HSN code is 2, 4, 6 or 8 digits long.", code);
  }
  return { valid: true, normalized: code, level };
}

/* ── FSSAI licence ───────────────────────────────────────────────────────── */

export type FssaiErrorCode =
  | "empty"
  | "not_digits"
  | "wrong_length"
  | "bad_prefix";

/**
 * FSSAI licence numbers are 14 digits. The first digit is 1 for a registration
 * and 2 for a state/central licence; anything else is a typo.
 */
export function validateFssai(input: string): IdResult<FssaiErrorCode> {
  const id = input.replace(/\D/g, "");
  if (!input.trim()) return bad("empty", "Enter an FSSAI licence number.", id);
  if (/[^\d\s]/.test(input))
    return bad("not_digits", "An FSSAI number is digits only.", id);
  if (id.length !== 14) {
    return bad(
      "wrong_length",
      `An FSSAI number is 14 digits — ${id.length} so far.`,
      id,
    );
  }
  if (id[0] !== "1" && id[0] !== "2") {
    return bad("bad_prefix", "An FSSAI number starts with 1 or 2.", id);
  }
  return { valid: true, normalized: id };
}

/**
 * Government photo-ID identifiers used in Indian KYC: Voter ID (EPIC),
 * driving licence, and passport.
 *
 * None of these carry a public checksum, so everything here is structural.
 * Real verification means the issuing authority's API — ECI, Parivahan/Sarathi,
 * or the Passport Seva portal respectively.
 */

import { RTO_STATE_CODES } from "./vehicle";

export interface IdResult<E extends string = string> {
  valid: boolean;
  normalized: string;
  error?: { code: E; message: string };
}

function ok<E extends string>(normalized: string): IdResult<E> {
  return { valid: true, normalized };
}

function bad<E extends string>(
  code: E,
  message: string,
  normalized: string,
): IdResult<E> {
  return { valid: false, normalized, error: { code, message } };
}

const upper = (input: string) => input.replace(/[\s-]/g, "").toUpperCase();

/* ── Voter ID (EPIC) ─────────────────────────────────────────────────────── */

const EPIC_RE = /^[A-Z]{3}[0-9]{7}$/;

export type VoterIdErrorCode = "empty" | "wrong_length" | "bad_shape";

/**
 * EPIC numbers are three letters (the Functional Constituency code) followed by
 * seven digits. Older cards used other shapes, but every card issued since the
 * 2000s follows this one.
 */
export function validateVoterId(input: string): IdResult<VoterIdErrorCode> {
  const id = upper(input);
  if (!input.trim()) return bad("empty", "Enter a Voter ID number.", id);
  if (id.length !== 10) {
    return bad(
      "wrong_length",
      `An EPIC number is 10 characters — ${id.length} so far.`,
      id,
    );
  }
  if (!EPIC_RE.test(id)) {
    return bad(
      "bad_shape",
      "A Voter ID looks like ABC1234567 — three letters, seven digits.",
      id,
    );
  }
  return ok(id);
}

/* ── Driving licence ─────────────────────────────────────────────────────── */

const DL_RE = /^([A-Z]{2})(\d{2})(\d{4})(\d{7})$/;

export type LicenceErrorCode =
  | "empty"
  | "wrong_length"
  | "bad_shape"
  | "unknown_state"
  | "bad_year";

export interface LicenceResult extends IdResult<LicenceErrorCode> {
  stateCode?: string;
  state?: string;
  rtoCode?: string;
  year?: number;
}

/**
 * Format is `SSRRYYYYNNNNNNN` — state, RTO office, year of issue, serial.
 * Printed with spaces or hyphens in practice, so we strip them first.
 */
export function validateDrivingLicence(input: string): LicenceResult {
  const dl = upper(input);
  if (!input.trim()) return bad("empty", "Enter a driving licence number.", dl);
  if (dl.length !== 15) {
    return bad(
      "wrong_length",
      `A licence number is 15 characters — ${dl.length} so far.`,
      dl,
    );
  }

  const match = DL_RE.exec(dl);
  if (!match) {
    return bad(
      "bad_shape",
      "A licence looks like MH1220110012345 — state, RTO, year, serial.",
      dl,
    );
  }

  const [, stateCode, rtoCode, yearStr] = match;
  const state = RTO_STATE_CODES[stateCode];
  if (!state)
    return bad(
      "unknown_state",
      `“${stateCode}” isn't a state code we recognise.`,
      dl,
    );

  const year = Number(yearStr);
  const thisYear = new Date().getFullYear();
  if (year < 1950 || year > thisYear) {
    return bad("bad_year", `“${yearStr}” isn't a plausible year of issue.`, dl);
  }

  return { valid: true, normalized: dl, stateCode, state, rtoCode, year };
}

/* ── Passport ────────────────────────────────────────────────────────────── */

const PASSPORT_RE = /^[A-PR-WY][0-9]{7}$/;

export type PassportErrorCode = "empty" | "wrong_length" | "bad_shape";

/**
 * Indian passports are one letter then seven digits. The letters Q, X and Z are
 * not used as the leading character, which is a cheap extra typo check.
 */
export function validatePassport(input: string): IdResult<PassportErrorCode> {
  const id = upper(input);
  if (!input.trim()) return bad("empty", "Enter a passport number.", id);
  if (id.length !== 8) {
    return bad(
      "wrong_length",
      `A passport number is 8 characters — ${id.length} so far.`,
      id,
    );
  }
  if (!PASSPORT_RE.test(id)) {
    return bad(
      "bad_shape",
      "A passport number looks like A1234567 — one letter, seven digits.",
      id,
    );
  }
  return ok(id);
}

/**
 * Indian vehicle registration number validation.
 *
 * Two live formats:
 *
 *   State series   MH 12 AB 1234   state + RTO district + series + number
 *   Bharat (BH)    22 BH 1234 AA   year + "BH" + number + series
 *
 * The BH series was introduced in 2021 for vehicles that move between states,
 * and its digits-first shape breaks any regex written only for the classic
 * format — which is why plenty of Indian insurance forms still reject it.
 */

const STATE_SERIES_RE = /^([A-Z]{2})(\d{1,2})([A-Z]{1,3})(\d{1,4})$/;
const BH_SERIES_RE = /^(\d{2})(BH)(\d{4})([A-Z]{1,2})$/;

export const RTO_STATE_CODES: Readonly<Record<string, string>> = {
  AP: "Andhra Pradesh",
  AR: "Arunachal Pradesh",
  AS: "Assam",
  BR: "Bihar",
  CG: "Chhattisgarh",
  CH: "Chandigarh",
  DD: "Daman & Diu",
  DL: "Delhi",
  DN: "Dadra & Nagar Haveli",
  GA: "Goa",
  GJ: "Gujarat",
  HP: "Himachal Pradesh",
  HR: "Haryana",
  JH: "Jharkhand",
  JK: "Jammu & Kashmir",
  KA: "Karnataka",
  KL: "Kerala",
  LA: "Ladakh",
  LD: "Lakshadweep",
  MH: "Maharashtra",
  ML: "Meghalaya",
  MN: "Manipur",
  MP: "Madhya Pradesh",
  MZ: "Mizoram",
  NL: "Nagaland",
  OD: "Odisha",
  OR: "Odisha (old code)",
  PB: "Punjab",
  PY: "Puducherry",
  RJ: "Rajasthan",
  SK: "Sikkim",
  TN: "Tamil Nadu",
  TR: "Tripura",
  TS: "Telangana",
  UK: "Uttarakhand",
  UA: "Uttarakhand (old code)",
  UP: "Uttar Pradesh",
  WB: "West Bengal",
  AN: "Andaman & Nicobar Islands",
};

export type VehicleFormat = "state" | "bharat";

export type VehicleErrorCode =
  | "empty"
  | "too_short"
  | "bad_shape"
  | "unknown_state";

export interface VehicleResult {
  valid: boolean;
  normalized: string;
  format?: VehicleFormat;
  stateCode?: string;
  state?: string;
  /** RTO district number — state format only. */
  districtCode?: string;
  series?: string;
  number?: string;
  /** Registration year — BH series only. */
  year?: string;
  formatted?: string;
  error?: { code: VehicleErrorCode; message: string };
}

function fail(
  code: VehicleErrorCode,
  message: string,
  normalized: string,
): VehicleResult {
  return { valid: false, normalized, error: { code, message } };
}

export function normalizeVehicleNumber(input: string): string {
  return input.replace(/[\s-]/g, "").toUpperCase();
}

export function validateVehicleNumber(input: string): VehicleResult {
  const reg = normalizeVehicleNumber(input);

  if (!input.trim()) return fail("empty", "Enter a registration number.", reg);
  if (reg.length < 6) {
    return fail(
      "too_short",
      "That's too short for a registration number.",
      reg,
    );
  }

  const bh = BH_SERIES_RE.exec(reg);
  if (bh) {
    const [, year, , number, series] = bh;
    return {
      valid: true,
      normalized: reg,
      format: "bharat",
      year: `20${year}`,
      number,
      series,
      formatted: `${year} BH ${number} ${series}`,
    };
  }

  const state = STATE_SERIES_RE.exec(reg);
  if (!state) {
    return fail(
      "bad_shape",
      "Use MH12AB1234, or 22BH1234AA for a Bharat series plate.",
      reg,
    );
  }

  const [, stateCode, districtCode, series, number] = state;
  const stateName = RTO_STATE_CODES[stateCode];
  if (!stateName) {
    return fail(
      "unknown_state",
      `“${stateCode}” isn't a state code we recognise.`,
      reg,
    );
  }

  return {
    valid: true,
    normalized: reg,
    format: "state",
    stateCode,
    state: stateName,
    districtCode,
    series,
    number,
    formatted: `${stateCode} ${districtCode} ${series} ${number}`,
  };
}
